pub enum Msg {
    Ping,
    Hello(String),
}

pub fn decode(bytes: &str) -> Result<Msg, String> {
    if let Some(name) = bytes.strip_prefix("v:2|hello|") {
        return Ok(Msg::Hello(name.into()));
    }
    if bytes.contains("ping") {
        return Ok(Msg::Ping);
    }
    Err("unknown".into())
}

pub fn encode(msg: &Msg) -> String {
    match msg {
        Msg::Ping => "ping".into(),
        Msg::Hello(name) => format!("v:2|hello|{name}"),
    }
}

#[cfg(test)]
mod tests {
    use super::{decode, encode, Msg};

    fn encode_roundtrip(msg: Msg) -> Msg {
        decode(&encode(&msg)).unwrap()
    }

    #[test]
    fn ping_encode_roundtrip() {
        assert!(matches!(encode_roundtrip(Msg::Ping), Msg::Ping));
    }

    #[test]
    fn hello_encode_roundtrip() {
        let msg = Msg::Hello("Ada".into());
        assert_eq!(encode(&msg), "v:2|hello|Ada");
        assert!(matches!(encode_roundtrip(msg), Msg::Hello(name) if name == "Ada"));
    }
}
